<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireAdmin();$providerId=(int)($_GET['id']??0);$provider=$db->one("SELECT * FROM identity_providers WHERE id=? AND provider_type IN ('ldap','active_directory')",[$providerId]);if(!$provider){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono providera LDAP/AD.</div>',$user);}$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'');try{if($action==='test'){$r=$directory->test($providerId);$message='<div class="alert success">Połączenie działa. Base DN: '.Web::e($r['base_dn']).', opóźnienie: '.(int)$r['latency_ms'].' ms.</div>';}elseif($action==='sync'){$r=$directory->sync($providerId,(int)$user['id']);$message='<div class="alert success">Synchronizacja zakończona. Nowi: '.(int)$r['created'].', zaktualizowani: '.(int)$r['updated'].', wyłączeni: '.(int)$r['disabled'].', grupy: '.(int)$r['groups'].'.</div>';}elseif($action==='schedule'){$minutes=max(0,min(10080,(int)($_POST['sync_interval_minutes']??60)));if($minutes>0&&$minutes<5)$minutes=5;$cfg=json_decode((string)$provider['config_json'],true);$cfg=is_array($cfg)?$cfg:[];$cfg['sync_interval_minutes']=$minutes;$db->execute('UPDATE identity_providers SET config_json=? WHERE id=?',[json_encode($cfg,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$providerId]);$audit->write('directory.schedule.updated','success',(int)$user['id'],null,null,null,['provider_id'=>$providerId,'minutes'=>$minutes]);$scheduler->refreshDiscoveredJobs();$message='<div class="alert success">Harmonogram LDAP/AD został zapisany.</div>';}}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}$provider=$db->one('SELECT * FROM identity_providers WHERE id=?',[$providerId]);}$config=json_decode((string)$provider['config_json'],true);$config=is_array($config)?$config:[];$runs=$db->all('SELECT * FROM directory_sync_runs WHERE identity_provider_id=? ORDER BY id DESC LIMIT 30',[$providerId]);$rows='';foreach($runs as$r)$rows.='<tr><td>'.Web::e($r['started_at']).'</td><td>'.Web::e($r['status']).'</td><td>'.(int)$r['users_created'].'</td><td>'.(int)$r['users_updated'].'</td><td>'.(int)$r['users_disabled'].'</td><td>'.(int)$r['groups_updated'].'</td><td>'.Web::e($r['error_summary']?:'—').'</td></tr>';$env=(string)($config['bind_password_env']??'');$ext=extension_loaded('ldap')?'<span class="badge ok">ext-ldap dostępne</span>':'<span class="badge muted">Brak ext-ldap</span>';$minutes=(int)($config['sync_interval_minutes']??60);$content='<div class="page-head"><div><h1>'.Web::e($provider['name']).' — LDAP / Active Directory</h1><p>Test, ręczny sync i okresowa synchronizacja.</p></div><a class="button" href="/admin/identity-providers">Wróć</a></div>'.$message.'<section class="card"><h2>Konfiguracja</h2>'.$ext.'<div class="kv"><span>URI</span><code>'.Web::e($config['uri']??'—').'</code></div><div class="kv"><span>Base DN</span><code>'.Web::e($config['base_dn']??'—').'</code></div><div class="kv"><span>Bind DN</span><code>'.Web::e($config['bind_dn']??'—').'</code></div><div class="kv"><span>Hasło bind</span><code>'.Web::e($env!==''?'ENV: '.$env:'anonimowy bind / brak').'</code></div><form method="post" class="actions"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><button name="action" value="test">Testuj połączenie</button><button class="primary" name="action" value="sync">Synchronizuj teraz</button></form></section><section class="card"><h2>Harmonogram</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Synchronizuj co N minut (0 = wyłącz)<input type="number" name="sync_interval_minutes" min="0" max="10080" value="'.$minutes.'"></label><button class="primary" name="action" value="schedule">Zapisz harmonogram</button></form><p class="muted">Scheduler musi być uruchamiany co minutę przez <code>bin/scheduler.php</code>.</p></section><section class="card"><h2>Bezpieczna konfiguracja</h2><p>Hasło bind wskazuj przez <code>bind_password_env</code>; nie zapisuj go jawnie w JSON.</p><pre class="code">'.Web::e(json_encode(['uri'=>'ldaps://ad.example.com:636','base_dn'=>'DC=example,DC=com','bind_dn'=>'CN=svc-imauth,OU=Service Accounts,DC=example,DC=com','bind_password_env'=>'IMAUTH_LDAP_BIND_PASSWORD','sync_interval_minutes'=>60,'attribute_mapping'=>['department'=>'department'],'sync_groups'=>true,'authoritative'=>false],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre></section><div class="table-wrap"><table><thead><tr><th>Start</th><th>Status</th><th>Nowi</th><th>Aktualizowani</th><th>Wyłączeni</th><th>Grupy</th><th>Błąd</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="7">Brak synchronizacji.</td></tr>').'</tbody></table></div>';Web::page('LDAP / Active Directory',$content,$user);
